// File validation: existence, size (<5MB), extension/MIME
const input = $input.first().json;
const rawFile = input.cv_content || '';
const fileType = input.file_type || 'tex';

if (!rawFile || rawFile.trim().length === 0) {
  throw new Error('REJECTION: Empty or missing CV content.');
}

if (rawFile.length > 5 * 1024 * 1024) {
  throw new Error('REJECTION: File exceeds 5MB size limit.');
}

// Basic LaTeX command stripper
let cleanText = rawFile;
if (fileType === 'tex') {
  cleanText = cleanText
    .replace(/\\documentclass\[.*?\]\{.*?\}/g, '')
    .replace(/\\usepackage(\[.*?\])?\{.*?\}/g, '')
    .replace(/\\begin\{.*?\}/g, '')
    .replace(/\\end\{.*?\}/g, '')
    .replace(/\\section\*?\{(.*?)\}/g, '\n=== SECTION: $1 ===\n')
    .replace(/\\textbf\{(.*?)\}/g, '$1')
    .replace(/\\textit\{(.*?)\}/g, '$1')
    .replace(/\\item/g, '• ')
    .replace(/\\(vspace|hspace)\{.*?\}/g, '')
    .replace(/\\[a-zA-Z]+/g, ' ')
    .replace(/[\\{}]/g, ' ');
}

return [{ json: { clean_text: cleanText.trim(), original_type: fileType, candidate_id: input.candidate_id || 'cand_' + Date.now() } }];

