// Schema validation & Contract 3.1 compliance check
const extracted = $input.first().json;

const requiredFields = [
  'schema_version',
  'candidate_id',
  'candidate_name',
  'email',
  'experience_years',
  'job_titles',
  'preferred_roles',
  'technical_skills',
  'programming_languages',
  'frameworks',
  'tools',
  'keywords',
  'education',
  'extraction_meta'
];

for (const field of requiredFields) {
  if (extracted[field] === undefined) {
    throw new Error(`CONTRACT ERROR: Missing required field '${field}'`);
  }
}

return [{ json: extracted }];
